<script lang="ts">
 import {onMount} from 'svelte';
 type Track={id:string;title:string;artist:string;streamUrl:string;duration?:number};
 let tracks=$state<Track[]>([]);let index=$state(0);let audio=$state<HTMLAudioElement>();let error=$state('');let playing=$state(false);let progress=$state(0);let expanded=$state(false);
 const current=$derived(tracks[index]);
 async function load(){try{const r=await fetch('/api/music/playlist');const j=await r.json();if(!r.ok)throw new Error(j.error);tracks=j.items??[];if(!tracks.length)error='暂无可播放曲目';}catch(e){error=e instanceof Error?e.message:'音乐服务暂不可用';}}
 function toggle(){if(!audio||!current)return;if(audio.paused)audio.play().then(()=>playing=true).catch(()=>error='请点击播放按钮开始音乐');else{audio.pause();playing=false}}
 function next(){if(!tracks.length)return;index=(index+1)%tracks.length;playing=false;setTimeout(()=>{if(audio)audio.play().then(()=>playing=true).catch(()=>{});},0)}
 function select(i:number){index=i;playing=false;setTimeout(()=>audio?.play().then(()=>playing=true).catch(()=>{}),0)}
 onMount(()=>{load();const open=()=>expanded=true;window.addEventListener('music:open',open);return()=>{window.removeEventListener('music:open',open);audio?.pause();}});
</script>
<section class="music-player" class:expanded aria-label="音乐播放器">
 <button class="player-orb" type="button" aria-expanded={expanded} aria-label={expanded?'收起音乐播放器':'展开音乐播放器'} onclick={()=>expanded=!expanded}><span class:spinning={playing}>♪</span></button>
 <div class="player-panel"><div class="player-head"><div><p class="kicker">LISTENING ROOM</p>{#if current}<strong>{current.title}</strong><small>{current.artist}</small>{:else}<small>{error||'正在读取音乐…'}</small>{/if}</div><button class="collapse" type="button" onclick={()=>expanded=false} aria-label="收起">×</button></div>
 {#if current}<audio bind:this={audio} src={current.streamUrl} ontimeupdate={()=>progress=audio?.currentTime??0} onended={next} preload="metadata"></audio><div class="controls"><button type="button" onclick={toggle} aria-label={playing?'暂停':'播放'}>{playing?'Ⅱ':'▶'}</button><input aria-label="播放进度" type="range" min="0" max={audio?.duration||current.duration||100} value={progress} oninput={e=>{if(audio)audio.currentTime=Number(e.currentTarget.value)}}/><button type="button" onclick={next} aria-label="下一首">›</button></div><div class="track-meta"><span>{index+1} / {tracks.length}</span><button type="button" onclick={()=>expanded=!expanded}>播放列表</button></div>{#if expanded&&tracks.length>1}<ol>{#each tracks as track,i}<li class:current={i===index}><button type="button" onclick={()=>select(i)}><span>{track.title}</span><small>{track.artist}</small></button></li>{/each}</ol>{/if}{/if}</div>
</section>
<style>
.music-player{position:fixed;right:24px;bottom:24px;z-index:35;font-size:0.75rem}.player-orb{width:50px;height:50px;border:1px solid color-mix(in srgb,var(--primary) 45%,var(--line));border-radius:50%;background:var(--surface);color:var(--primary);box-shadow:0 10px 30px #17233b25;font-size:1.375rem;cursor:pointer}.player-orb span{display:block}.spinning{animation:spin 3s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.player-panel{position:absolute;right:0;bottom:62px;width:280px;padding:15px;background:var(--panel-bg);border:1px solid var(--line);border-radius:16px;box-shadow:0 18px 46px #17233b30;opacity:1;pointer-events:auto;transform:none;transition:.2s ease}.music-player:not(.expanded) .player-panel{width:210px;padding:10px;bottom:58px}.music-player:not(.expanded) .player-panel .controls,.music-player:not(.expanded) .player-panel .track-meta,.music-player:not(.expanded) .collapse{display:none}.music-player.expanded .player-panel{width:280px}.player-head{display:flex;justify-content:space-between;gap:10px}.kicker{margin:0 0 5px;color:var(--primary);font:0.625rem/1.4 'DM Mono',monospace;letter-spacing:.14em}.player-head strong{display:block;line-height:1.4}.player-head small{display:block;color:var(--muted);font-size:0.6875rem}.collapse,.track-meta button{border:0;background:none;color:var(--muted);cursor:pointer}.controls{display:flex;align-items:center;gap:8px;margin-top:13px}.controls button{flex:0 0 42px;width:42px;height:42px;min-height:42px;padding:0;display:grid;place-items:center;border:0;border-radius:50%;background:color-mix(in srgb,var(--primary) 10%,var(--surface));color:var(--text);cursor:pointer}.controls input{flex:1;min-width:0;accent-color:var(--primary)}.track-meta{display:flex;justify-content:space-between;color:var(--muted);font-size:0.625rem;margin-top:9px}.player-panel ol{max-height:180px;overflow:auto;padding:7px 0 0;margin:7px 0 0;border-top:1px solid var(--line);list-style:none}.player-panel li button{width:100%;border:0;background:none;text-align:left;padding:6px;border-radius:7px;color:var(--text);cursor:pointer}.player-panel li.current button,.player-panel li button:hover{background:var(--soft)}.player-panel li span,.player-panel li small{display:block}.player-panel li small{color:var(--muted);font-size:0.625rem}@media(min-width:761px){.music-player:not(.expanded){display:none}}@media(max-width:760px){.music-player{right:14px;bottom:14px}.player-panel{width:min(280px,calc(100vw - 28px))}}
</style>
